import{_ as n,o as t,c as e,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"项目实战","description":"规划五个按复杂度递进的 Python Agent 完整项目，覆盖 RAG、工具调用、持久化工作流、受控数据访问与多 Agent 协作。","frontmatter":{"title":"项目实战","description":"规划五个按复杂度递进的 Python Agent 完整项目，覆盖 RAG、工具调用、持久化工作流、受控数据访问与多 Agent 协作。"},"headers":[],"relativePath":"py-agent/architecture/projects/index.md","filePath":"py-agent/architecture/projects/index.md","lastUpdated":1785311412000}'),r={name:"py-agent/architecture/projects/index.md"};function l(p,a,i,d,c,o){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="项目实战" tabindex="-1">项目实战 <a class="header-anchor" href="#项目实战" aria-label="Permalink to &quot;项目实战&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组不再用概念总结或验收清单代替项目实现。五个项目分别覆盖一种主要系统形态，并按“RAG 应用 → 工具型 Agent → 持久化工作流 → 数据 Agent → 多 Agent 系统”递进。每个项目都会独立交付可运行源码、自动化测试、容器化环境和验收结果。</p><h2 id="_1-分组目标" tabindex="-1">1. 分组目标 <a class="header-anchor" href="#_1-分组目标" aria-label="Permalink to &quot;1. 分组目标&quot;">​</a></h2><p>完成本分组后，读者应能独立完成以下工作：</p><ul><li>把业务需求转换为接口、状态、数据和安全契约；</li><li>在普通 RAG、单 Agent、固定工作流和多 Agent 之间作出有依据的选择；</li><li>使用 LangChain、LangGraph、FastAPI、PostgreSQL 和 Redis 组成真实应用；</li><li>为模型、工具、检索、状态和外部副作用编写可重复测试；</li><li>从干净环境启动服务，执行验收样例，并解释失败与恢复路径。</li></ul><h2 id="_2-项目规划" tabindex="-1">2. 项目规划 <a class="header-anchor" href="#_2-项目规划" aria-label="Permalink to &quot;2. 项目规划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>项目</th><th>类型</th><th>主要结果</th><th>核心技术</th></tr></thead><tbody><tr><td>1</td><td><a href="/py-agent/architecture/projects/enterprise-knowledge-qa-system">企业知识问答系统</a></td><td>RAG 应用</td><td>完成文档入库、权限检索、引用回答、反馈与评测闭环</td><td>LangChain、FastAPI、PostgreSQL、pgvector</td></tr><tr><td>2</td><td><a href="/py-agent/architecture/projects/aftersales-ticket-agent">售后工单 Agent</a></td><td>工具型 Agent</td><td>查询订单、判断方案、请求确认并幂等执行售后动作</td><td>LangChain Agent、Middleware、FastAPI、PostgreSQL、Redis</td></tr><tr><td>3</td><td><a href="/py-agent/architecture/projects/contract-review-workflow">合同审查工作流</a></td><td>持久化工作流</td><td>解析合同、并行检查风险、人工复核并从中断处恢复</td><td>LangGraph、PostgreSQL Checkpointer、后台任务、对象存储</td></tr><tr><td>4</td><td><a href="/py-agent/architecture/projects/data-analysis-agent">数据分析 Agent</a></td><td>受控数据 Agent</td><td>理解指标、生成受限 SQL、执行查询并输出可追溯分析</td><td>LangChain、SQLAlchemy、PostgreSQL、查询沙箱</td></tr><tr><td>5</td><td><a href="/py-agent/architecture/projects/research-collaboration-system">研究协作系统</a></td><td>多 Agent 系统</td><td>规划研究、并行取证、撰写与审校报告并控制预算</td><td>LangGraph Multi-Agent、FastAPI、任务队列、PostgreSQL</td></tr></tbody></table><h2 id="_3-递进关系" tabindex="-1">3. 递进关系 <a class="header-anchor" href="#_3-递进关系" aria-label="Permalink to &quot;3. 递进关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>企业知识问答系统</span></span>
<span class="line"><span>  └─ 检索、引用与评测</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>售后工单 Agent</span></span>
<span class="line"><span>  └─ 工具、权限与副作用</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>合同审查工作流</span></span>
<span class="line"><span>  └─ 状态、并行、中断与恢复</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>数据分析 Agent</span></span>
<span class="line"><span>  └─ 动态决策、受控执行与结果解释</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>研究协作系统</span></span>
<span class="line"><span>  └─ 角色协作、共享状态、预算与终止</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>前四个项目分别建立一种核心能力，第五个项目才组合多 Agent。这样可以先证明单 Agent 或固定工作流不足，再承担协作成本。</p><h2 id="_4-单个项目的完成标准" tabindex="-1">4. 单个项目的完成标准 <a class="header-anchor" href="#_4-单个项目的完成标准" aria-label="Permalink to &quot;4. 单个项目的完成标准&quot;">​</a></h2><p>每个项目正文统一采用“需求 → 架构 → 目录 → 分步实现 → 测试 → 部署 → 验收”，并满足以下硬要求：</p><ol><li>提供完整项目目录和实际源码，不保留未完成标记、被省略的函数或未定义接口；</li><li>从干净环境可以安装依赖、启动服务并执行至少一条端到端主路径；</li><li>真实模型和外部服务有明确配置，测试使用可替换适配器而不是伪造固定结论；</li><li>正常路径、权限拒绝、超时、重试、重复请求和恢复路径都有自动化测试；</li><li>Docker Compose 能启动项目依赖，健康检查能够区分存活与就绪；</li><li>验收结论来自实际命令、测试和评测结果，不在运行前预写“全部通过”；</li><li>生产范围没有实现的能力必须明确排除，不能放在“后续应当处理”的清单里冒充完成内容。</li></ol><h2 id="_5-编写顺序" tabindex="-1">5. 编写顺序 <a class="header-anchor" href="#_5-编写顺序" aria-label="Permalink to &quot;5. 编写顺序&quot;">​</a></h2><p>项目正文按表中顺序逐篇生成。每次只完成一个项目，并在进入下一个项目之前完成代码运行、测试、内容检查和整站构建，防止五个项目同时扩写后重复同一批错误。</p>`,16)])])}const g=n(r,[["render",l]]);export{b as __pageData,g as default};
